  private void btn_minimize_Click(object sender, EventArgs e)
  {
    this.WindowState = FormWindowState.Minimized;
  }

  private void btn_maximize_Click(object sender, EventArgs e)
  {
    if (this.WindowState != FormWindowState.Maximized)
      this.WindowState = FormWindowState.Maximized;
    else
      this.WindowState = FormWindowState.Normal;
  }

  public void btn_close_Click(object sender, EventArgs e)
  {
    try
    {
      if (clsVar.varRuntime.MachineID == 1 | clsVar.varRuntime.MachineID == 2 | clsVar.varRuntime.MachineID == 3 | clsVar.varRuntime.MachineID == 4 | clsVar.varRuntime.MachineID == 5 | clsVar.varRuntime.MachineID == 6 | clsVar.varRuntime.MachineID == 7 | clsVar.varRuntime.MachineID == 8 | clsVar.varRuntime.MachineID == 10)
      {
        if (clsAppMarbleVars.cMachine.runSystem.Run)
        {
          F_Intro.appMachine1.ShowWarning(buLangTranslate.preMotionWarning.SystemisRunning, Color.Gold);
          return;
        }
        if (clsAppMarbleVars.cMachine.runSystem.Pause)
        {
          F_Intro.appMachine1.ShowWarning(buLangTranslate.preMotionWarning.SsytemisPaused, Color.Gold);
          return;
        }
        clsLocalCommand.Exit();
      }
      if (clsVar.varRuntime.MachineID != 9)
        return;
      if (clsAppMarbleVars.cMachine.runSystem.Run)
        F_Intro.appMachine3.ShowWarning(buLangTranslate.preMotionWarning.SystemisRunning, Color.Gold);
      else if (clsAppMarbleVars.cMachine.runSystem.Pause)
        F_Intro.appMachine3.ShowWarning(buLangTranslate.preMotionWarning.SsytemisPaused, Color.Gold);
      else
        clsLocalCommand.Exit();
    }
    catch (Exception ex)
    {
    }
  }

  private void spn_Enter(object sender, EventArgs e)
  {
    buSpin buSpin = sender as buSpin;
    buSpin.Display.BackColor = buEyeVars.parVisual.colorDataFocus;
    buSpin.SelectAll();
  }

  public void spn_Leave(object sender, EventArgs e)
  {
    buSpin buSpin = sender as buSpin;
  }

  private void spn_ValueClicked(object sender, EventArgs e)
  {
    buSpin buSpin = sender as buSpin;
    if (!AppBool.TouchPad)
      return;
    F_KeyPadNumV1 fKeyPadNumV1 = new F_KeyPadNumV1();
    fKeyPadNumV1.StartPosition = FormStartPosition.CenterParent;
    fKeyPadNumV1.Caption = buSpin.Caption.Caption;
    fKeyPadNumV1.ShowDialog(buSpin.Value.ToString());
    if (buNumeric5.IsNumeric(fKeyPadNumV1.Value))
      buSpin.Value = double.Parse(fKeyPadNumV1.Value);
  }

  private void lbl_warning_Click(object sender, EventArgs e) => this.lbl_warning.Visible = false;

  private void F_Machine1_KeyDown(object sender, KeyEventArgs e)
  {
  }

  protected override void Dispose(bool disposing)
  {
    if (disposing && this.components != null)
      this.components.Dispose();
